# Identify distinct pattern regions
def find_regions(grid, threshold=0.1):
    """Find distinct non-zero regions in the grid."""
    rows, cols = grid.shape
    region_sets = []
    visited = np.zeros((rows, cols), dtype=bool)

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] > 0 and not visited[r, c]:
                # Found a new region
                region = []
                to_visit = [(r, c)]
                while to_visit:
                    cr, cc = to_visit.pop()
                    if not visited[cr, cc]:
                        visited[cr, cc] = True
                        region.append((cr, cc))
                        # Add neighbors
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr, nc] > 0 and not visited[nr, nc]:
                                    to_visit.append((nr, nc))
                region_sets.append(region)
    return region_sets

regions = find_regions(grid)
print(f"Found {len(regions)} distinct regions:")
for i, region in enumerate(regions):
    rows = [r for r, c in region]
    cols_set = {c for r, c in region}
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols_set), max(cols_set)
    print(f"  Region {i}: ({min_r},{min_c}) to ({max_r},{max_c})")

